const __inputRaw = workflowContext.actions['Merge'].outputs.body;
const __inputValues = Array.isArray(__inputRaw) ? __inputRaw : [__inputRaw];
const items = __inputValues.map(value =>
  value && typeof value === 'object' && 'json' in value ? value : { json: value }
);
const __unwrap = value => {
  if (Array.isArray(value)) {
    return value.map(item =>
      item && typeof item === 'object' && 'json' in item ? item.json : item
    );
  }
  return value && typeof value === 'object' && 'json' in value ? value.json : value;
};
const __node = name => {
  const output = workflowContext.actions[name]?.outputs;
  const raw = output && typeof output === 'object' && 'body' in output
    ? output.body
    : output;
  const values = Array.isArray(raw) ? raw : [raw];
  const wrapped = values.map(value =>
    value && typeof value === 'object' && 'json' in value ? value : { json: value }
  );
  return {
    item: wrapped[0],
    first: () => wrapped[0],
    last: () => wrapped[wrapped.length - 1],
    all: () => wrapped
  };
};

const $json = items[0]?.json ?? {};
const $input = {
  item: items[0],
  first: () => items[0],
  last: () => items[items.length - 1],
  all: () => items
};
const __result = (() => {
function extractOpenAIText(it) {
  // Après Merge by position, OpenAI est sous la clé "0"
  const openai = it.json?.["0"];

  if (openai?.content && Array.isArray(openai.content)) {
    const t = openai.content.map(x => x?.text).filter(Boolean).join("\n");
    if (t) return t;
  }

  // fallback (au cas où)
  if (typeof openai?.text === "string" && openai.text.trim()) return openai.text.trim();

  return null;
}

function extractDriveUrl(it) {
  return it.json?.webContentLink || it.json?.webViewLink || null;
}

const rows = items.map((it, idx) => ({
  n: idx + 1,
  desc: extractOpenAIText(it) || "No description",
  url: extractDriveUrl(it) || "No link",
}));

return [{
  json: {
    image1Description: rows[0]?.desc || "No description",
    image2Description: rows[1]?.desc || "No description",
    image3Description: rows[2]?.desc || "No description",

    image1Url: rows[0]?.url || "No link",
    image2Url: rows[1]?.url || "No link",
    image3Url: rows[2]?.url || "No link",
    imageUrls: rows.map(r => r.url).filter(u => u && u !== "No link"),

    allDescriptions: rows.map(r => `Image ${r.n}: ${r.desc}`).join("\n\n"),
  }
}];

})();
return { body: __unwrap(__result) };

