{
  "prompt": @{JSON.stringify(body('Edit_Fields_contactSheetPrompt')?['contactSheetPrompt'] || '')},
  "image_urls": {{ JSON.stringify(
    (() => {
      const v = $('Get image nanobanana').item.json.image_nanobanana;

      // 1) déjà un array
      if (Array.isArray(v)) return v;

      // 2) string JSON "[...]" -> parse
      if (typeof v === 'string' && v.trim().startsWith('[')) {
        try { return JSON.parse(v); } catch (e) {}
      }

      // 3) string simple -> le mettre en array
      if (typeof v === 'string' && v.trim()) return [v.trim()];

      // 4) fallback vide
      return [];
    })()
  ) }},
  "resolution": "1K",
  "aspect_ratio": "3:2",
  "output_format": "png"
}
